    for (int i = l; i <= r; i++) {
        int c = cc[i];
        if (!used[c]) {
            used[c] = true;
            count++;
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b, l, r;
    cin >> a >> b >> l >> r;
    l -= 1;
    r -= 1;
    int totalAB = a + b;
    int repetitions = 4;
    vector<int> pattern(totalAB * repetitions);
    int offsetH = l / totalAB;
    l -= offsetH * totalAB;
    r -= offsetH * totalAB;
    int segmentCount = (r - l + 1) / totalAB;
    if (segmentCount > 2) r -= (segmentCount - 2) * totalAB;
    int diff = max(a - b, 1);
    for (int rep = 0; rep < repetitions; rep++) {
        for (int k = 0; k < a - diff; k++)
            pattern[totalAB * rep + k] = k;
        for (int k = 0; k < diff; k++)
            pattern[totalAB * rep + a - diff + k] = (rep % 2 == 0) ? a - diff + k : a + k;
    }
    int minCount = a + a;
    for (int shiftA = 1; shiftA <= diff; shiftA++) {
        for (int k = 0; k < b; k++)
            pattern[totalAB * 0 + a + k] = pattern[totalAB * 0 + a - shiftA];
        for (int shiftB1 = 1; shiftB1 <= diff; shiftB1++) {
