                        pattern[totalAB * 3 + a + k] = pattern[totalAB * 3 + a - shiftB3];
                    minCount = min(minCount, countDistinct(pattern, l, r));
                }
            }
        }
    }
    cout << minCount << "\n";
    return 0;
}
